# Fix the output construction

rows = 29
cols = 27

output = [[0] * cols for _ in range(rows)]

for row in range(rows):
    for col in range(cols):
        val = 9
        if row == 3:
            # Full line of 7s, last 3 cols become 1s
            if col >= cols - 3:
                val = 1
            else:
                val = 7
        elif row == 21:
            # 7s in cols 0-16, last 3 cols of that line (14-16) become 1s
            if 14 <= col <= 16:
                val = 1
            elif 0 <= col <= 16:
                val = 7
        output[row][col] = val

print("Row 3:", output[3])
print("Row 21:", output[21])
